    if (dim == 1) {
        return hermite_values;
    }

    // Base case: H_1(x) = 2x
    hermite_values.push_back(2.0 * x);

    // Compute H_2(x) through H_{2*dim-2}(x)
    for (size_t n = 2; n < 2 * dim - 1; ++n) {
        double next_hermite = 2.0 * x * hermite_values[n-1] - 2.0 * (n-1) * hermite_values[n-2];
        hermite_values.push_back(next_hermite);
    }

    return hermite_values;

